```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy auctions_select on public.auctions
  for select to authenticated
  using (true);

create policy bids_select on public.bids
  for select to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1 from public.auctions a
      where a.id = bids.auction_id
      and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_seller_id uuid;
  v_ends_at timestamptz;
  v_starting_price numeric(10, 2);
  v_min_increment numeric(10, 2);
  v_highest_bid numeric(10, 2);
  v_has_bids boolean;
  v_new_highest numeric(10, 2);
begin
  if auth.uid() is null then
    raise exception 'Caller must be signed in';
  end if;

  select a.seller_id, a.ends_at, a.starting_price, a.min_increment, a.highest_bid, (a.highest_bid is not null)
  into v_seller_id, v_ends_at, v_starting_price, v_min_increment, v_highest_bid, v_has_bids
  from public.auctions a
  where a.id = p_auction_id;

  if not found then
    raise exception 'Auction does not exist';
  end if;

  if v_ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_seller_id = auth.uid() then
    raise exception 'Cannot bid on your own auction';
  end if;

  if p_amount <= v_starting_price then
    raise exception 'Bid must be above the starting price';
  end if;

  if v_has_bids then
    if p_amount <= v_highest_bid + v_min_increment then
      raise exception 'Bid must be at least min_increment above the current highest bid';
    end if;
  else
    if p_amount <= v_starting_price then
      raise exception 'Bid must be above the starting price';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on public.auctions from anon, authenticated;
revoke all on public.bids from anon, authenticated;
grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant usage, select on sequence public.bids_id_seq to authenticated;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
```

```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy auctions_select on public.auctions
  for select to authenticated
  using (true);

create policy bids_select on public.bids
  for select to authenticated
  using (bidder_id = auth.uid() or exists (select 1 from public.auctions a where a.id = bids.auction_id and a.seller_id = auth.uid()));

create function public.place_bid(p_auction_id bigint, p_amount numeric) returns numeric
language plpgsql
security definer
as $$
declare
  v_seller_id uuid;
  v_ends_at timestamptz;
  v_starting_price numeric(10, 2);
  v_min_increment numeric(10, 2);
  v_highest_bid numeric(10, 2);
  v_bids_count int;
  v_new_highest numeric(10, 2);
begin
  if auth.uid() is null then
    raise exception 'Caller must be signed in';
  end if;

  select a.seller_id, a.ends_at, a.starting_price, a.min_increment, a.highest_bid, count(*)
  into v_seller_id, v_ends_at, v_starting_price, v_min_increment, v_highest_bid, v_bids_count
  from public.auctions a
  where a.id = p_auction_id;

  if not found then
    raise exception 'Auction does not exist';
  end if;

  if v_ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_seller_id = auth.uid() then
    raise exception 'Cannot bid on your own auction';
  end if;

  if p_amount <= v_starting_price then
    raise exception 'Bid must be above the starting price';
  end if;

  if v_bids_count = 0 then
    v_new_highest := p_amount;
  else
    if p_amount <= v_highest_bid + v_min_increment then
      raise exception 'Bid must be at least % above the current highest bid', v_highest_bid + v_min_increment;
    end if;
    v_new_highest := p_amount;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  update public.auctions
  set highest_bid = v_new_highest,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return v_new_highest;
end;
$$;
