alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create policy classes_select on public.classes
  for select to authenticated
  using (true);

create policy class_spots_select on public.class_spots
  for select to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1 from public.classes c
      where c.id = class_spots.class_id
      and c.instructor_id = auth.uid()
    )
  );

create policy class_spots_insert on public.class_spots
  for insert to authenticated
  with check (
    user_id = auth.uid()
    and status in ('enrolled', 'waitlisted')
    and exists (
      select 1 from public.classes c
      where c.id = class_id
      and (
        (status = 'enrolled' and c.capacity > (select count(*) from public.class_spots cs where cs.class_id = c.id and cs.status = 'enrolled'))
        or (status = 'waitlisted' and exists (
          select 1 from public.classes cc
          where cc.id = c.id
          and cc.capacity <= (select count(*) from public.class_spots cs where cs.class_id = cc.id and cs.status = 'enrolled')
        ))
      )
    )
  );

create policy class_spots_update on public.class_spots
  for update to authenticated
  using (
    user_id = auth.uid()
    and status = 'waitlisted'
  )
  with check (
    user_id = auth.uid()
    and status = 'enrolled'
    and exists (
      select 1 from public.classes c
      where c.id = class_id
      and c.capacity > (select count(*) from public.class_spots cs where cs.class_id = c.id and cs.status = 'enrolled')
    )
  );

create policy class_spots_delete on public.class_spots
  for delete to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1 from public.classes c
      where c.id = class_id
      and c.instructor_id = auth.uid()
    )
  );

create policy classes_insert on public.classes
  for insert to authenticated
  with check (false);

create policy classes_update on public.classes
  for update to authenticated
  using (false);

create policy classes_delete on public.classes
